describe('Tab Navigation for Interactive Elements', () => {
  beforeEach(() => {
    cy.visit('/interactive-page');
  });

  it('should navigate through all interactive elements using Tab', () => {
    // Verify initial state
    cy.get('[data-testid="page-title"]').should('be.visible');
    cy.get('[data-testid="page-title"]').should('contain', 'Interactive Page');

    // Tab through elements
    cy.get('[data-testid="page-title"]').tab();
    cy.get('[data-testid="navigation-menu"]').should('be.visible');
    cy.get('[data-testid="navigation-menu"]').tab();
    cy.get('[data-testid="main-content"]').should('be.visible');
    cy.get('[data-testid="sidebar"]').should('be.visible');
    cy.get('[data-testid="footer"]').should('be.visible');

    // Verify navigation order
    cy.get('[data-testid="page-title"]').should('have.css', 'display', 'block');
    cy.get('[data-testid="navigation-menu"]').should('have.css', 'display', 'block');
    cy.get('[data-testid="main-content"]').should('have.css', 'display', 'block');
    cy.get('[data-testid="sidebar"]').should('have.css', 'display', 'block');
    cy.get('[data-testid="footer"]').should('have.css', 'display', 'block');

    // Verify focus is on the last element
    cy.get('[data-testid="footer"]').should('have.focus');
  });

  it('should handle Tab navigation when elements have no visible focus state', () => {
    // Navigate to a page with hidden elements
    cy.visit('/hidden-elements-page');

    // Tab through elements
    cy.get('[data-testid="page-title"]').tab();
    cy.get('[data-testid="navigation-menu"]').tab();
    cy.get('[data-testid="main-content"]').tab();
    cy.get('[data-testid="sidebar"]').tab();

    // Verify focus is on the last visible element
    cy.get('[data-testid="footer"]').should('have.focus');

    // Verify hidden elements are not focused
    cy.get('[data-testid="hidden-input"]').should('not.have.focus');
    cy.get('[data-testid="hidden-button"]').should('not.have.focus');

    // Verify Tab key presses are handled correctly
    cy.get('[data-testid="page-title"]').type('{tab}');
    cy.get('[data-testid="navigation-menu"]').type('{tab}');
    cy.get('[data-testid="main-content"]').type('{tab}');
    cy.get('[data-testid="sidebar"]').type('{tab}');

    // Verify focus remains on the last visible element
    cy.get('[data-testid="footer"]').should('have.focus');
  });
});
